export const sharedScenarios: readonly SharedScenario[] = [...authoredScenarios].sort((a, b) => a.oodsComponentId < b.oodsComponentId ? -1 : a.oodsComponentId > b.oodsComponentId ? 1 : 0).map(scenario => {
  const behavior = componentBehaviors[scenario.oodsComponentId];
  return { ...scenario, interaction: behavior.interaction,
    interactionReason: 'interactionReason' in behavior ? behavior.interactionReason : undefined,
    event: behavior.event };
});

/**
 * s222-m03 (#2502 ruling 16): an empty value, which React, Vue and the HTML renderer must show alike, as "Unknown time"
 * with no empty datetime. It stays out of sharedScenarios, which holds exactly one documented example per component.
 */
export const relativeTimestampEmptyScenario: SharedScenario = {
  id: 'relative-timestamp-empty', oodsComponentId: 'RelativeTimestamp',
  props: { datetime: '' }, slots: {},
  initialState: { content: 'empty' },
  renderExpectation: { name: 'render', trigger: 'mount with an empty datetime', expected: 'Unknown time is visible and no datetime attribute is emitted' },
  assertions: ['an empty value reads Unknown time', 'an empty datetime is omitted, never emitted empty'],
  interaction: componentBehaviors.RelativeTimestamp.interaction,
  interactionReason: componentBehaviors.RelativeTimestamp.interactionReason,
  event: componentBehaviors.RelativeTimestamp.event,
};
